# undirected variant & static connectivity control
import collections
W=(60917,80117); D=600
ev=[e for e in events if W[0]<=e[2]<=W[1]]
# undirected temporal reach
best={1010:None}
paths={1010:[]}
for u,v,t in ev:
    for a,b in ((u,v),(v,u)):
        aa=best.get(a,'X')
        if aa=='X': continue
        ok=(aa is None) or (aa<=t<=aa+D)
        if not ok: continue
        if b not in best or (best[b] is not None and t<best[b]):
            best[b]=t; paths[b]=paths[a]+[(u,v,t)]
print("undirected reach 883:", 883 in best, len(best))
print(paths.get(883))
# static directed connectivity ignoring time
adj=collections.defaultdict(set)
for u,v,t in ev: adj[u].add(v)
seen={1010}; q=[1010]
while q:
    x=q.pop()
    for y in adj[x]:
        if y not in seen: seen.add(y); q.append(y)
print("static directed reach 883:", 883 in seen, len(seen))
